using SharpTS.Tests.Infrastructure;
using Xunit;

namespace SharpTS.Tests.SharedTests;

public sealed class PrimitivePrototypeOwnDescriptorsTests
{
    public static IEnumerable<object[]> Cases()
    {
        yield return ["number-string-original", "const p:any=Number.prototype,key='probe';Object.defineProperty(p,key,{value:7});const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.getOwnPropertyDescriptor(p,key)!.value,d[key]===undefined,Reflect.ownKeys(d).includes(key));\n", "7 false true\n"];
        yield return ["number-symbol-original", "const p:any=Number.prototype,key=Symbol('probe');Object.defineProperty(p,key,{value:7});const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.getOwnPropertyDescriptor(p,key)!.value,d[key]===undefined,Reflect.ownKeys(d).includes(key));\n", "7 false true\n"];
        yield return ["boolean-string-original", "const p:any=Boolean.prototype,key='probe';Object.defineProperty(p,key,{value:7});const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.getOwnPropertyDescriptor(p,key)!.value,d[key]===undefined,Reflect.ownKeys(d).includes(key));\n", "7 false true\n"];
        yield return ["boolean-symbol-original", "const p:any=Boolean.prototype,key=Symbol('probe');Object.defineProperty(p,key,{value:7});const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.getOwnPropertyDescriptor(p,key)!.value,d[key]===undefined,Reflect.ownKeys(d).includes(key));\n", "7 false true\n"];
        yield return ["number-intrinsic-attributes", "const p:any=Number.prototype;const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.hasOwn(d,'constructor'),d.constructor.value===Number,d.constructor.writable,d.constructor.enumerable,d.constructor.configurable,d.toString.value===p.toString,d.toString.enumerable);\n", "true true true false true true false\n"];
        yield return ["number-accessors-without-getter-read", "const p:any=Number.prototype;let calls=0;function read(this:any){calls++;return this.tag}function write(this:any,v:any){}const s=Symbol('held');Object.defineProperty(p,'held',{get:read,set:write,enumerable:true,configurable:true});Object.defineProperty(p,s,{get:read,configurable:true});const d:any=Object.getOwnPropertyDescriptors(p);console.log(calls,d.held.get===read,d.held.set===write,d[s].get===read,d.held.enumerable,d[s].enumerable);console.log(d.held.get.call({tag:9}),calls);\n", "0 true true true true false\n9 1\n"];
        yield return ["number-integer-string-symbol-order", "const p:any=Number.prototype;const s1=Symbol('s1'),s2=Symbol('s2');p.b=1;p[10]=2;p.a=3;p[2]=4;p[s1]=5;p[s2]=6;const d:any=Object.getOwnPropertyDescriptors(p);let result='';for(const k of Reflect.ownKeys(d)){if(typeof k==='string'&&(k==='2'||k==='10'||k==='b'||k==='a'))result+=k+',';else if(typeof k==='symbol')result+=(k===s1?'s1':'s2')+',';}console.log(result);\n", "2,10,b,a,s1,s2,\n"];
        yield return ["number-inherited-and-deleted-excluded", "const p:any=Number.prototype;const own=Symbol('own'),inherited=Symbol('parent'),base:any={inherited:9};base[inherited]=8;Object.setPrototypeOf(p,base);p.gone=1;delete p.gone;p.probe=2;p[own]=7;const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.hasOwn(d,'inherited'),Object.hasOwn(d,'gone'),Object.hasOwn(d,'probe'),Object.getOwnPropertySymbols(d).includes(inherited),d[own].value);\n", "false false true false 7\n"];
        yield return ["number-undefined-and-result-attributes", "const p:any=Number.prototype;Object.defineProperty(p,'probe',{value:undefined});const d:any=Object.getOwnPropertyDescriptors(p),outer=Object.getOwnPropertyDescriptor(d,'probe')!;console.log(Object.hasOwn(d,'probe'),d.probe.value===undefined,d.probe.writable,d.probe.enumerable,d.probe.configurable,outer.writable,outer.enumerable,outer.configurable);\n", "true true false false false true true true\n"];
        yield return ["number-descriptor-snapshot-and-value-identity", "const p:any=Number.prototype;const original:any={n:1};p.probe=original;const d:any=Object.getOwnPropertyDescriptors(p);p.probe=2;console.log(d.probe.value===original,Object.getOwnPropertyDescriptors(p).probe.value,p.probe);\n", "true 2 2\n"];
        yield return ["number-symbol-identity-and-string-collision", "const p:any=Number.prototype;const a=Symbol('same'),b=Symbol('same');p[String(a)]=3;p[a]=7;p[b]=9;const d:any=Object.getOwnPropertyDescriptors(p),keys=Object.getOwnPropertySymbols(d);console.log(keys.length,keys[0]===a,keys[1]===b,d[a].value,d[b].value,d[String(a)].value);\n", "2 true true 7 9 3\n"];
        yield return ["number-frozen-owned-flags", "const p:any=Number.prototype;p.probe=7;Object.freeze(p);const d:any=Object.getOwnPropertyDescriptors(p);console.log(d.probe.value,d.probe.writable,d.probe.enumerable,d.probe.configurable,d.constructor.writable,d.constructor.configurable);\n", "7 false true false false false\n"];
        yield return ["boolean-intrinsic-attributes", "const p:any=Boolean.prototype;const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.hasOwn(d,'constructor'),d.constructor.value===Boolean,d.constructor.writable,d.constructor.enumerable,d.constructor.configurable,d.toString.value===p.toString,d.toString.enumerable);\n", "true true true false true true false\n"];
        yield return ["boolean-accessors-without-getter-read", "const p:any=Boolean.prototype;let calls=0;function read(this:any){calls++;return this.tag}function write(this:any,v:any){}const s=Symbol('held');Object.defineProperty(p,'held',{get:read,set:write,enumerable:true,configurable:true});Object.defineProperty(p,s,{get:read,configurable:true});const d:any=Object.getOwnPropertyDescriptors(p);console.log(calls,d.held.get===read,d.held.set===write,d[s].get===read,d.held.enumerable,d[s].enumerable);console.log(d.held.get.call({tag:9}),calls);\n", "0 true true true true false\n9 1\n"];
        yield return ["boolean-integer-string-symbol-order", "const p:any=Boolean.prototype;const s1=Symbol('s1'),s2=Symbol('s2');p.b=1;p[10]=2;p.a=3;p[2]=4;p[s1]=5;p[s2]=6;const d:any=Object.getOwnPropertyDescriptors(p);let result='';for(const k of Reflect.ownKeys(d)){if(typeof k==='string'&&(k==='2'||k==='10'||k==='b'||k==='a'))result+=k+',';else if(typeof k==='symbol')result+=(k===s1?'s1':'s2')+',';}console.log(result);\n", "2,10,b,a,s1,s2,\n"];
        yield return ["boolean-inherited-and-deleted-excluded", "const p:any=Boolean.prototype;const own=Symbol('own'),inherited=Symbol('parent'),base:any={inherited:9};base[inherited]=8;Object.setPrototypeOf(p,base);p.gone=1;delete p.gone;p.probe=2;p[own]=7;const d:any=Object.getOwnPropertyDescriptors(p);console.log(Object.hasOwn(d,'inherited'),Object.hasOwn(d,'gone'),Object.hasOwn(d,'probe'),Object.getOwnPropertySymbols(d).includes(inherited),d[own].value);\n", "false false true false 7\n"];
        yield return ["boolean-undefined-and-result-attributes", "const p:any=Boolean.prototype;Object.defineProperty(p,'probe',{value:undefined});const d:any=Object.getOwnPropertyDescriptors(p),outer=Object.getOwnPropertyDescriptor(d,'probe')!;console.log(Object.hasOwn(d,'probe'),d.probe.value===undefined,d.probe.writable,d.probe.enumerable,d.probe.configurable,outer.writable,outer.enumerable,outer.configurable);\n", "true true false false false true true true\n"];
        yield return ["boolean-descriptor-snapshot-and-value-identity", "const p:any=Boolean.prototype;const original:any={n:1};p.probe=original;const d:any=Object.getOwnPropertyDescriptors(p);p.probe=2;console.log(d.probe.value===original,Object.getOwnPropertyDescriptors(p).probe.value,p.probe);\n", "true 2 2\n"];
        yield return ["boolean-symbol-identity-and-string-collision", "const p:any=Boolean.prototype;const a=Symbol('same'),b=Symbol('same');p[String(a)]=3;p[a]=7;p[b]=9;const d:any=Object.getOwnPropertyDescriptors(p),keys=Object.getOwnPropertySymbols(d);console.log(keys.length,keys[0]===a,keys[1]===b,d[a].value,d[b].value,d[String(a)].value);\n", "2 true true 7 9 3\n"];
        yield return ["boolean-frozen-owned-flags", "const p:any=Boolean.prototype;p.probe=7;Object.freeze(p);const d:any=Object.getOwnPropertyDescriptors(p);console.log(d.probe.value,d.probe.writable,d.probe.enumerable,d.probe.configurable,d.constructor.writable,d.constructor.configurable);\n", "7 false true false false false\n"];
        yield return ["ordinary-object-control", "let calls=0;const s=Symbol('s'),p:any={a:1};Object.defineProperty(p,s,{get(){calls++;return 7},configurable:true});const d:any=Object.getOwnPropertyDescriptors(p);console.log(d.a.value,calls,typeof d[s].get,Reflect.ownKeys(d)[1]===s);\n", "1 0 function true\n"];
        yield return ["nullish-target-control", "for(const p of [null,undefined]){try{Object.getOwnPropertyDescriptors(p as any)}catch(e){console.log(e instanceof TypeError)}}\n", "true\ntrue\n"];
    }

    public static IEnumerable<object[]> Modes() => Cases().SelectMany(row =>
        new[] { ExecutionMode.Interpreted, ExecutionMode.Compiled }.Select(mode =>
            new object[] { row[0], row[1], row[2], mode }));

    [Theory, MemberData(nameof(Modes))]
    public void ReturnsOwnStringAndSymbolDescriptorsWithoutInvokingGetters(string name, string source, string expected, ExecutionMode mode)
    {
        Assert.NotEmpty(name);
        Assert.Equal(expected, TestHarness.Run(source, mode));
    }
}
